from .refs import CITE as R

SH = F.shot
EV, EX, API, S_ = F.EV, F.EX, F.API, F.S


def FG(prefix, caption, width=5.4):
    """Figure from docs/figures whose file name starts with `prefix` (f01_, f02_ ...); a visible note if it has not been produced."""
    hits = sorted(glob.glob(os.path.join(F.FIGS, prefix + "*.png")))
    if not hits:
        return P(f"[figure {prefix} not yet produced: {caption}]")
    return FIG(hits[0], caption, width)


def S(name, caption, base=5.4, max_h=3.6):
    """Screenshot figure with a width that keeps the picture on one page."""
    return FIG(SH(name), caption, F.shot_w(SH(name), base, max_h))


def SP(a, b):
    """Two screenshots side by side: a, b are (file, caption)."""
    return PAIR([(SH(a[0]), a[1]), (SH(b[0]), b[1])], 2.95)


