def _core():
    rows = [[r["cover"].replace(".png", ""), f"{r['payload_bytes']:,}", f"{r['used_pct']}", r["psnr_db"], r["ssim"], r["encrypt_ms"], r["embed_ms"], r["extract_ms"], r["decrypt_ms"]]
            for r in EV["quality_and_speed"] if r["fits"]]
    cap = [[c["cover"].replace(".png", ""), f"{c['width']} x {c['height']}", f"{c['pixels']:,}", f"{c['max_bundle_bytes']:,}", c["max_bundle_kib"], c["max_bits_per_pixel"]] for c in EV["capacity"]]
    return [
        H2("8.3 Core evaluation: imperceptibility, capacity and speed"),
        P(f"The core evaluation (`ml/eval.py`) hides random-length files in the six covers with an RSA-3072 key. Of the 30 combinations, **{S_['runs']}** fit and **{S_['runs_skipped_too_large']}** are refused by the capacity check, "
          f"which is the intended behaviour. All {S_['runs']} round trips restored the file byte for byte. PSNR was never below **{S_['psnr_db_min']} dB** (mean {S_['psnr_db_mean']} dB) and SSIM never below **{S_['ssim_min']}** "
          f"(mean {S_['ssim_mean']}). The median times were {S_['median_encrypt_ms']} ms to encrypt and wrap, {S_['median_embed_ms']} ms to embed, {S_['median_extract_ms']} ms to extract and {S_['median_decrypt_ms']} ms to unwrap and decrypt."),
        TAB("Capacity of each cover (1 bit per colour value, 32-bit length header)", ["Cover", "Size (px)", "Pixels", "Max bundle (B)", "Max bundle (KiB)", "Bits per pixel"], cap,
            widths=[2.0, 0.9, 0.8, 0.9, 0.9, 0.8], align=["l", "c", "r", "r", "r", "c"], size=9.5),
        TAB("Quality and speed of the 22 runs that fit (RSA-3072, median of 3 repeats)",
            ["Cover", "Payload (B)", "Used %", "PSNR (dB)", "SSIM", "Enc (ms)", "Embed (ms)", "Extr (ms)", "Dec (ms)"], rows,
            widths=[1.55, 0.7, 0.5, 0.65, 0.7, 0.5, 0.55, 0.5, 0.5], align=["l", "r", "r", "r", "r", "r", "r", "r", "r"], size=8.5),
        P("The eight refused combinations are 128 KiB into every cover except the landscape, 64 KiB into the 451 x 300 and 200 x 200 covers, and 16 KiB into the 200 x 200 cover. "
          "PSNR falls as the share of the cover used grows, from 74.615 dB at 0.45 % (1 KiB into the landscape) to 52.479 dB at 73.4 % (64 KiB into the 600 x 400 coffee image); SSIM stays above 0.9958. "
          "RSA unwrap dominates the time of the cryptographic step and is almost independent of payload size, while embedding grows with the payload to 1.674 ms for 128 KiB."),
        FG("f03_", "Maximum hidden bundle per cover: capacity is proportional to the pixel count at 3.0 bits per pixel.", 5.0),
    ]


def _fill():
    fs = EX["fill_study"]
    rows = []
    for f in sorted({r["fill"] for r in fs["rows"]}):
        sel = [r for r in fs["rows"] if r["fill"] == f]
        rows.append([f"{int(f * 100)} %", f"{statistics.mean(r['used_pct'] for r in sel):.1f}", f"{statistics.mean(r['psnr_mean'] for r in sel):.2f}",
                     f"{min(r['psnr_mean'] for r in sel):.2f}", f"{statistics.mean(r['psnr_theory'] for r in sel):.2f}",
                     f"{statistics.mean(r['ssim_mean'] for r in sel):.5f}", f"{min(r['ssim_mean'] for r in sel):.5f}"])
    return [
        H2("8.4 Fill-ratio study and the closed-form PSNR model"),
        P(f"The core evaluation uses a few payload sizes. To cover the whole range the fill-ratio study fills each of the six covers to 1, 5, 10, 25, 50, 75 and 100 % of capacity with random payloads of five different seeds (RSA-2048). "
          f"Because the embedded bits are ciphertext, each bit equals the cover's own least significant bit half of the time, so half of the used values change by exactly one. This gives a closed-form model:"),
        EQ("MSE = 0.5 x n_bits / N,    PSNR = 10 log10(255^2 / MSE)    (N = width x height x 3 colour values, n_bits = 8 x (bundle bytes + 4))"),
        P(f"Measured PSNR matches the model within **{fs['max_abs_dev_vs_theory_db']} dB** over all 42 cover and fill combinations, and the standard deviation across payload seeds never exceeded {fs['max_psnr_std_db']} dB. "
          "The model also gives the floor: with every value used, PSNR is 10 log10(255^2 / 0.5) = 51.14 dB, and the measurement at 100 % fill is 51.14-51.17 dB. PSNR is therefore above 50 dB at every fill level on every cover. "
          "SSIM depends on the picture as well as the amount of data and is lowest (0.992893) for the smooth procedural landscape at 100 % fill."),
        TAB("Imperceptibility against fill ratio (mean over the six covers and five payload seeds)",
            ["Fill", "Capacity used %", "PSNR mean (dB)", "PSNR min (dB)", "PSNR model (dB)", "SSIM mean", "SSIM min"], rows,
            widths=[0.6, 0.95, 0.95, 0.95, 0.95, 0.9, 0.9], align=["c"] * 7, size=9.5),
        FG("f01_", "Measured PSNR against fill ratio for the six covers, with the closed-form model; the 50 dB line marks the usual limit of visibility.", 5.4),
        FG("f02_", "Measured SSIM against fill ratio for the six covers.", 5.0),
        FG("f12_", "Absolute difference between cover and stego, amplified, for the 22 % fill of the Send screen: the changes are scattered values of 1 in the rows used.", 5.4),
    ]


def _timing():
    a = API
    rs = EX["rsa_study"]
    rsa_rows = [[r["rsa_bits"], f"{r['keygen_ms_median']} ({r['keygen_ms_min']}-{r['keygen_ms_max']})", r["encrypt_wrap_ms_median"], r["unwrap_decrypt_ms_median"], r["wrapped_key_bytes"], r["overhead_bytes"]] for r in rs]
    keys = ["login", "keys/generate 3072", "send (21 KiB memo, 512x512 cover, RSA-3072)", "send (21 KiB memo, 1280x720 cover)", "receive (RSA-3072)",
            "analysis metrics", "histogram + bit planes, first render", "robustness (9 attacks)", "benchmark/run (6 covers x 3 sizes, RSA-2048)", "log (100 rows)"]
    api_rows = [[k, a[k]["n"], a[k]["median_ms"], a[k].get("p95_ms", a[k].get("max_ms"))] for k in keys]
    return [
        H2("8.5 Key size, stage timings and API latency"),
        P("Key size changes three things: the time to generate a key, the time to unwrap, and the bundle overhead. Wrapping is cheap (0.16-0.24 ms) because it uses the public exponent 65537; unwrapping uses the private key and grows roughly "
          "with the cube of the key size. Key generation varies strongly from run to run because it searches for primes, so the range is shown beside the median."),
        TAB("RSA key size study (4 KiB payload; 30 wraps and unwraps, 5 key generations)",
            ["RSA bits", "Key generation (ms), median (min-max)", "Encrypt + wrap (ms)", "Unwrap + decrypt (ms)", "Wrapped key (B)", "Bundle overhead (B)"], rsa_rows,
            widths=[0.6, 1.8, 0.95, 1.0, 0.9, 0.95], align=["c"] * 6, size=9.5),
        FG("f05_", "RSA key size against key-generation time, wrap time and unwrap time (median).", 5.0),
        P("For a 4 KiB message the 3072-bit key costs 94 ms to open and adds 128 bytes more than the 2048-bit key; the 4096-bit key costs 221 ms and 256 bytes more. The overhead is a fixed 401, 529 or 657 bytes "
          "(wrapped key, magic, lengths, nonce, header, tag), which matters only for very small covers: it is 3 % of the 14.6 KiB capacity of the 200 x 200 image."),
        FG("f04_", "Median time of the four cryptographic and embedding stages for payloads of 1 to 128 KiB (RSA-3072): the unwrap dominates and everything else is below 2 ms.", 5.2),
        P("End to end, through HTTP, the picture changes because the web layer adds the work the library benchmark leaves out: PNG encoding and the image-quality measures. "
          "A send of the 21 KiB memo into a 512 x 512 cover takes 437.7 ms at the median, and 1,873.4 ms into a 1280 x 720 cover; the cryptography is about 0.15 ms of that, and the log of the send shows `png_encode` at 100-190 ms and `metrics` (PSNR and SSIM) at about 300 ms. "
          "Receiving takes 198.2 ms, mostly the RSA unwrap. Login costs 286.7 ms because bcrypt is deliberately slow."),
        TAB("API latency on the measurement machine (127.0.0.1, demo user)", ["Call", "Runs", "Median (ms)", "p95 or max (ms)"], api_rows,
            widths=[3.6, 0.6, 0.9, 1.1], align=["l", "c", "r", "r"], size=9.5),
        FG("f10_", "API latency per call (median, with 95th percentile or maximum).", 5.2),
    ]


def _plain():
    pe = EX["plain_vs_encrypted"]
    rows = [[r["payload"], r["kind"], r["bytes"], r["ones_fraction"], r["entropy_bits_per_byte"], r["changed_pct_of_embedded_bits"], r["psnr_db"]] for r in pe["rows"]]
    return [
        H2("8.6 What encryption adds to the embedded bits"),
        P(f"A natural question is whether encryption costs image quality. The experiment hides each sample file twice in the {pe['cover'].replace('.png', '')} cover, once as plain bytes and once as the encrypted bundle. "
          "In both cases about half of the embedded bits change a value (49.1-51.6 %), so PSNR depends on the number of bits and not on their kind: encryption costs nothing in imperceptibility. "
          "What changes is the statistics of the stream. Plain files are unbalanced (fraction of 1-bits 0.42-0.46) and have low entropy (4.2-4.4 bits per byte for the text files), so they can be read directly once the carrier bits are found; "
          "the encrypted bundle has a fraction of 1-bits of 0.49-0.51 and 7.58-7.99 bits per byte, bounded only by the small sample size."),
        TAB("Plain versus encrypted payloads in the same cover", ["Payload", "Kind", "Bytes", "Fraction of 1-bits", "Entropy (bits/byte)", "Embedded bits that flip a value (%)", "PSNR (dB)"], rows,
            widths=[1.5, 0.8, 0.6, 0.8, 0.8, 1.0, 0.7], align=["l", "l", "r", "c", "c", "c", "c"], size=9),
        FG("f07_", "Fraction of 1-bits and byte entropy of plain files and of the encrypted bundles.", 5.0),
    ]


def _robust():
    rob = EV["robustness"]
    rows = [[r["label"], f"{r['recovered']} / 6", r["mean_bit_error_rate"]] for r in rob] + [[r["attack"], f"{r['recovered']} / {r['of']}", "-"] for r in EX["extra_attacks"]]
    return [
        H2("8.7 Robustness: what survives"),
        P("Robustness was tested on all six covers with the 2,774-byte `accounts.csv` and an RSA-3072 key. Each attack modifies the stego image, then the real extraction and decryption are attempted and the recovered file is hashed. "
          "The nine attacks of the application are in the first block of the table; a further nine (re-encodings, a colour reduction and geometric changes) were added in `scripts/run_experiments.py` on the same six images with RSA-2048."),
        TAB("Payload recovery after each attack (6 covers)", ["Attack", "Recovered", "Mean LSB error rate"], rows,
            widths=[3.0, 1.1, 1.5], align=["l", "c", "c"], size=9.5),
        P("The pattern is exact. Anything that preserves pixel values keeps the payload: PNG re-save, PNG at compression 9, PNG with an alpha channel added, lossless WebP, and a crop that removes only rows below the payload. "
          "Anything that changes pixel values or their order loses it: JPEG even at quality 100, lossy WebP, Gaussian noise of sigma 1, resizing, grayscale conversion, a 256-colour palette, rotation, flipping and cropping columns. "
          "The error rate of the lossy attacks is 49-50 %, which is what a coin toss gives, so there is nothing left for an error-correcting code to repair; the batch objective of measuring robustness is met, and the answer is that the scheme is robust to lossless handling only. "
          "The 5 attacks of 18 that were survived are lossless or leave the payload rows untouched."),
        FG("f06_", "Payload recovery and LSB error rate for the 18 attacks over the six covers.", 5.4),
    ]


def _steg():
    sa = EX["steganalysis"]
    t = EX["tamper_study"]
    pick = [r for r in sa["rows"] if r["fill"] in (0.1, 0.5, 1.0)]
    rows = [[r["cover"].replace(".png", ""), f"{int(r['fill'] * 100)} %", r["chi2_p_cover_prefix"], r["chi2_p_stego_prefix"], r["ws_estimate_cover"], r["ws_estimate_stego"]] for r in pick]
    tam = [[k, 40, "; ".join(f"{a} x{b}" for a, b in v.items())] for k, v in t["by_field"].items()]
    return [
        H2("8.8 Steganalysis and tamper evidence"),
        P(f"Imperceptible does not mean undetectable, so the stego images were attacked with two classical detectors. The chi-square test of Westfeld and Pfitzmann [{R['westfeld']}] checks whether the counts of the value pairs (2k, 2k+1) have been equalised; "
          f"a p-value near 1 means the least significant bit plane has been overwritten with random-looking bits. It was applied to the embedded prefix, which is an oracle because it assumes the length of the payload is known. "
          f"The stego prefix gave p between 0.97 and 1.00 in all {sa['chi2_total']} cases (six covers, five fill levels); the clean cover gave p below 0.5 in {sa['chi2_detected']} of them. "
          f"In three cases (the cat image at 10 and 25 % and the small coffee image at 10 %) the clean image's prefix was already near-equalised, so the test could not separate cover from stego there."),
        P(f"The weighted-stego estimator [{R['ws']}], [{R['wsrev']}] is blind: it estimates the fraction of overwritten samples from the whole image. Its estimate tracks the true fill (about 0.10, 0.50 and 1.00 for the three levels shown, within 0.30 at the low end), "
          "with a natural-image bias of 0.08-0.18 on four of the six covers and about 0 on the other two. A steganalyst with such a tool can therefore tell that these images carry data when the fill is medium or high. "
          "Because the embedding starts at the first pixel and does not depend on a key, the location of the payload is also known to anyone who knows the algorithm; the secrecy rests on the encryption, not on the hiding."),
        TAB("Steganalysis of the stego images (selected fill levels; full 30 cases in the experiment file)", ["Cover", "Fill", "Chi-square p, cover", "Chi-square p, stego", "Weighted-stego, cover", "Weighted-stego, stego"], rows,
            widths=[1.8, 0.5, 1.0, 1.0, 1.0, 1.0], align=["l", "c", "c", "c", "c", "c"], size=9),
        FG("f08_", "Chi-square p-value and weighted-stego estimate against the true fill, for cover and stego images.", 5.4),
        P(f"Tamper evidence is the opposite case: the receiver must notice any change. One stego LSB was flipped at a random position inside each field of the bundle, 40 times per field, {t['trials']} flips in all (astronaut cover, RSA-2048, 4 KiB payload). "
          f"All {t['trials']} were rejected and **{t['accepted_with_wrong_data']}** produced a wrong file. Flips in the magic, the key-length field and the wrapped key are caught by the format checks and the RSA unwrap; "
          "flips in the nonce, the ciphertext and the tag fail the AES-GCM tag check; flips in the 32-bit length header either give an invalid length (13 cases) or shift the bundle and fail the tag (27 cases)."),
        TAB("Outcome of single-bit tampering by field", ["Field", "Flips", "Outcome"], tam, widths=[1.5, 0.5, 4.4], align=["l", "c", "l"], size=9),
        FG("f09_", "Outcome of 240 single-bit flips by bundle field: every flip is rejected.", 5.0),
        P(f"A further check shows that encrypting the same file 50 times under one key gives 50 different nonces and 50 different wrapped keys, and two bundles differ in {EX['freshness']['mean_bit_difference_between_bundles'] * 100:.1f} % of their bits on average, "
          "so an observer cannot tell that two images carry the same file."),
    ]


def _compare():
    return [
        H2("8.9 Comparison with the base paper and the supporting papers"),
        P(f"The base paper [{R['base']}] and CipherVeil solve different problems, and the comparison below is therefore qualitative. ProSt hides single secret bits at a secret position among random decoy bits so that an untrusted cloud can compute "
          "on them with Fredkin gates; it proves that the adversary's advantage is of order 1/n in the number n of positions and recommends n of at least 2^20 (about 10^6). It reports no PSNR, SSIM or capacity, because its goal is private computation, "
          "not transmitting a file. Its reported runtime of 8.38 s is for a 17-gate circuit on a 128 x 128 x 3 image on an Intel Core i5-1135G7 and cannot be compared with the milliseconds of CipherVeil, which does no gate evaluation."),
        TAB("Qualitative comparison (different goals, covers and payloads)", ["Aspect", f"ProSt (base paper) [{R['base']}]", f"SCReedSolo [{R['screed']}]", f"Memristive ciphers [{R['memr']}]", "CipherVeil (this project)"],
            [["Goal", "Compute on hidden bits in an untrusted cloud", "Robust hiding of text, audio or image", "Lightweight ciphers in memory hardware", "Send a file with two layers of protection"],
             ["Embedding", "Secret bit among random decoy LSBs", "Shuffled, encrypted and RS-coded LSB, 3 bpp", "LSB hiding of cipher output (demonstration)", "Sequential 1-bit LSB in RGB, 3.0 bpp"],
             ["Encryption", "None on the payload; location secrecy", "Fernet (symmetric)", "Trivium, Grain-128a on IMPLY logic", "AES-256-GCM + RSA-OAEP-SHA256"],
             ["Reported quality", "Not reported", "PSNR 51.774, 57.653, 52.888 dB; SSIM 0.996, 0.936, 0.996", "PSNR table for 256 x 256 gray images", "PSNR 52.479-74.615 dB up to 73 % fill; 51.14 dB at 100 %; SSIM 0.9929-0.99999"],
             ["Robustness", "Not applicable", "Reed-Solomon against bit corruption", "Not studied", "Lossless only; no error correction"],
             ["Security argument", "Provable, advantage of order 1/n", "Empirical steganalysis tools", "Hardware energy and steps", "Standard primitives; detectable by chi-square and weighted-stego"],
             ["Speed", "8.38 s (17 gates, 128 x 128 x 3)", "Not given in comparable form", "Energy reductions up to 42 % and 44 %", "0.15 ms encrypt, 0.25 ms embed, 86 ms unwrap (median)"]],
            widths=[0.85, 1.35, 1.35, 1.2, 1.65], align=["l"] * 5, size=8.5),
        P(f"SCReedSolo [{R['screed']}] reports PSNR 51.774 dB and SSIM 0.996 for 5.46 million characters of text in a 14589 x 8423 x 3 image, 57.653 dB and 0.936 for audio in a 21188 x 30328 x 3 image, and 52.888 dB and 0.996 for a 100 x 100 x 3 image in the 512 x 512 Lenna image. "
          "These use very different covers and payloads, so the numbers are of the same order as CipherVeil's 52.5-74.6 dB up to 73 % fill, not better or worse. SCReedSolo adds shuffling and error correction, which CipherVeil does not have; "
          "CipherVeil adds public-key key transport and authenticated encryption, which SCReedSolo does not have. The memristive paper concerns hardware (energy and step reductions of up to 42 % and 44 %) and offers no software result to compare."),
        FG("f11_", "PSNR range reported for SCReedSolo and measured for CipherVeil. Covers and payloads differ, so the bars indicate order of magnitude only.", 5.2),
        P("What CipherVeil adopts from the base paper is the LSB carrier and the idea of exchanging a secret between sender and receiver by standard cryptography. "
          "What it does not implement is homomorphic computation on hidden bits, decoy-bit location hiding and a provable-security argument; Chapter 10 lists how a key-dependent pixel selection could move towards the base paper's location secrecy."),
    ]


def _samples():
    return [
        H2("8.10 Sample inputs and outputs"),
        TAB("The five messages of the demonstration session", ["Op", "Input file (bytes)", "Cover", "PSNR (dB)", "Result"],
            [["5", "confidential_memo.pdf (21,517)", "astronaut_512x512", "57.642", "bundle 22,063 B, 22.445 % of the cover; received byte for byte (op 10)"],
             ["6", "confidential_memo.pdf (21,517)", "coffee_small_200x200", "-", "blocked: needs 22,063 B, cover holds 14,996 B"],
             ["7", "accounts.csv (2,774)", "coffee_600x400", "65.513", "bundle 3,310 B, 3.678 % of the cover; stego PNG produced"],
             ["8", "settings.json (99)", "generated_landscape_1280x720", "78.419", "bundle 634 B, 0.183 % of the cover; stego PNG produced"],
             ["9", "meeting_notes.txt (169)", "rocket_640x427", "72.707", "bundle 709 B, 0.692 % of the cover; SSIM 0.999986"]],
            widths=[0.4, 1.9, 1.7, 0.7, 2.1], align=["c", "l", "l", "c", "l"], size=9),
        P("The input is any file up to 25 MB and the output is a PNG. The same hash is shown at both ends: for the memo the SHA-256 begins `89acd543` before sending and after receiving. "
          "A second output of the receive step, the failed one, is shown below. The smaller the payload relative to the cover, the higher the PSNR, as the closed-form model predicts: 99 bytes in the landscape gives 78.419 dB, 21,517 bytes in the astronaut image gives 57.642 dB."),
    ]


def _cases():
    return [
        H2("8.11 Success and failure analysis"),
        P("**Where the system succeeds.** Every file that fits is restored byte for byte (22 of 22 in the core evaluation, plus the 240 tamper trials and 50 repeated encryptions that all decrypted correctly). "
          "The stego image is visually identical to the cover (largest change 1 of 255, PSNR above 51.14 dB at every fill level). Any modification of the bundle is detected before anything is released. "
          "A wrong key, an image without a payload and a file that is not an image are each refused with a specific message."),
        SP(("07_send_capacity_blocked.png", "Failure case: a 22,063-byte bundle does not fit the 14,996-byte 200 x 200 cover; the send is refused with the exact numbers."),
           ("12_receive_wrong_key.png", "Failure case: receiving with the Spare keypair; the RSA unwrap fails and no data is released.")),
        P("**Where it fails, by design.** The two screens above show refusals that protect the user. The failures that cost data are different: JPEG, noise, resizing, rotation, grayscale and palette conversion destroy the payload (Section 8.7), "
          "and the receiver is told only that no payload was found, because after such an attack the length header is garbage. The image cannot be repaired, only resent. "
          "A chat application or a social site that recompresses the picture will make a sent message unreadable."),
        P("**Where it is weaker than it looks.** The imperceptibility numbers are excellent, but the chi-square test flags the images and the weighted-stego estimate recovers the fill (Section 8.8). A user who reads PSNR above 50 dB as safe from detection draws the wrong conclusion. "
          "Low fill is the best defence: a 169-byte note in a 640 x 427 image changes 0.35 % of the values."),
    ]


def _limits():
    return [
        H2("8.12 Limitations of these results"),
        B("Six covers, all committed test images or a procedural landscape; no camera photographs, no images that were already JPEG-compressed before conversion, and no large corpus.",
          "Four small synthetic payloads and random payloads; no real confidential documents were used.",
          "One machine and one operating condition; timings vary by 10-30 % with load. Only the embedding, PSNR and SSIM numbers are load-independent.",
          "Steganalysis used only two classical detectors, and the chi-square test was applied with the payload length known. Sample-pair, RS and deep-learning detectors were not run, so the detectability reported is a lower bound.",
          "Robustness was measured with a single payload (`accounts.csv`) and a single noise seed; the bottom-crop result holds only while the bundle lies in the retained rows.",
          "The comparison with the base paper is qualitative; its provable-security claim was not reproduced and was not in scope.",
          "The web interface was driven by a script to capture screens, not tested with an assertion-based browser suite, and no usability study with real users was done."),
    ]


