def blocks():
    out = [H1("CHAPTER 8: RESULTS AND OUTPUT SCREENS"),
           P("This chapter reports what was measured. It begins with the set-up, shows every screen of the working product, then gives the core evaluation of imperceptibility, capacity and speed, the fill-ratio study, "
             "the key-size and latency measurements, robustness, steganalysis and tamper evidence, the comparison with the base paper, sample inputs and outputs, a success and failure analysis and the objectives against outcomes. "
             "Where a result is weaker than the product's screens suggest, the text says so.")]
    for fn in (_setup, _screens, _core, _fill, _timing, _plain, _robust, _steg, _compare, _samples, _cases, _limits, _objectives):
        out += fn()
    return out
